using System.Globalization;
using System.Text.Json;
using System.Windows;
using System.Windows.Controls;
namespace PhotoTrail.Windows;
public partial class MainWindow {
 MapWorkspaceSnapshot? mapWorkspace;Guid? editingFavorite;bool fillingMapSettings,userMapMoved,mapLocationPending;int mapViewEpoch;
 void LoadMapWorkspace(){try{mapWorkspace=MapWorkspace.Read(MapWorkspace.DefaultPath);fillingMapSettings=true;MapSelectedOnly.IsChecked=mapWorkspace.State.SelectedOnly;MapStartWithDevice.IsChecked=mapWorkspace.State.StartWithDevice;GoogleLayerChoice.SelectedIndex=Array.IndexOf(new[]{"roadmap","satellite","hybrid","terrain"},mapWorkspace.State.GoogleLayer);userMapMoved=mapWorkspace.State.OpenView is not null;RefreshFavorites();FavoriteStatus.Text=L10n.Message(L10n.Text("已读取本机手填收藏；预览不应用，不自动采用查询文字。"));}catch(Exception){mapWorkspace=null;FavoriteStatus.Text=L10n.Message(L10n.Text("收藏/地图偏好不可读取，未自动覆盖；当前输入可保留。"));}finally{fillingMapSettings=false;}}
 void RefreshFavorites(){if(mapWorkspace is null)return;FavoriteList.ItemsSource=FavoritesExpanded.IsChecked==true?mapWorkspace.State.Favorites:mapWorkspace.State.Favorites.Take(2).ToArray();}
 void PersistMapState(MapWorkspaceState state){if(mapWorkspace is null)throw new InvalidOperationException(L10n.Text("先解决收藏读取失败；未覆盖。"));mapWorkspace=MapWorkspace.Save(MapWorkspace.DefaultPath,mapWorkspace,state);}
 private void FavoritesExpand(object s,RoutedEventArgs e){if(IsLoaded)RefreshFavorites();}
 private void ReloadFavorites(object s,RoutedEventArgs e){LoadMapWorkspace();}
 private void NewFavorite(object s,RoutedEventArgs e){editingFavorite=null;FavoriteList.SelectedIndex=-1;FavoriteName.Text=FavoriteNote.Text=FavoriteLongitude.Text=FavoriteLatitude.Text="";FavoriteStatus.Text=L10n.Message(L10n.Text("新收藏仅接收手填名称、备注和WGS84坐标；未从服务复制内容。"));}
 private void SaveFavorite(object s,RoutedEventArgs e){try{if(!double.TryParse(FavoriteLongitude.Text,NumberStyles.Float,CultureInfo.InvariantCulture,out var lon)||!double.TryParse(FavoriteLatitude.Text,NumberStyles.Float,CultureInfo.InvariantCulture,out var lat))throw new ArgumentException(L10n.Text("请输入WGS84经纬度数字。"));var value=new FavoriteLocation(editingFavorite??Guid.NewGuid(),FavoriteName.Text,FavoriteNote.Text,new(lon,lat));if(mapWorkspace is null)throw new InvalidOperationException(L10n.Text("收藏库读取失败，不能覆盖。"));PersistMapState(mapWorkspace.State with{Favorites=MapWorkspace.Upsert(mapWorkspace.State.Favorites,value)});editingFavorite=value.Id;RefreshFavorites();FavoriteStatus.Text=L10n.Message(L10n.Text("手填收藏已保存到本机；未改照片或草稿。"));}catch(Exception){FavoriteStatus.Text=L10n.Message(L10n.Text("收藏未保存：参数、文件或另一实例冲突；输入和旧文件保持。请核对后重读。"));}}
 private void DeleteFavorite(object s,RoutedEventArgs e){if(mapWorkspace is null||editingFavorite is not {} id)return;try{PersistMapState(mapWorkspace.State with{Favorites=mapWorkspace.State.Favorites.Where(f=>f.Id!=id).ToArray()});RefreshFavorites();NewFavorite(s,e);FavoriteStatus.Text=L10n.Message(L10n.Text("仅删除该本机收藏；照片、轨迹和草稿保留。"));}catch(Exception){FavoriteStatus.Text=L10n.Message(L10n.Text("收藏未删除，旧文件保持，请重读后核对。"));}}
 private void MoveFavoriteUp(object s,RoutedEventArgs e){if(mapWorkspace is null||editingFavorite is not {} id)return;try{var items=mapWorkspace.State.Favorites.ToArray();int i=Array.FindIndex(items,f=>f.Id==id);if(i<=0)return;(items[i-1],items[i])=(items[i],items[i-1]);PersistMapState(mapWorkspace.State with{Favorites=items});RefreshFavorites();FavoriteStatus.Text=L10n.Message(L10n.Text("收藏顺序已保存；照片选择和草稿保持。"));}catch(Exception){FavoriteStatus.Text=L10n.Message(L10n.Text("顺序未保存，旧文件保持。"));}}
 private void PreviewFavorite(object s,SelectionChangedEventArgs e){if(FavoriteList.SelectedItem is not FavoriteLocation value)return;editingFavorite=value.Id;FavoriteName.Text=value.Name;FavoriteNote.Text=value.Note;FavoriteLongitude.Text=value.Point.Longitude.ToString("R",CultureInfo.InvariantCulture);FavoriteLatitude.Text=value.Point.Latitude.ToString("R",CultureInfo.InvariantCulture);if(busy||renameRecoveryRequired){FavoriteStatus.Text=L10n.Message(L10n.Text("仅查看收藏；任务或恢复中不更新定位预览。"));return;}InvalidateBatchTrack();ClearMatchMarker();currentPreview=value.Point;previewAltitude=null;previewMethod="MANUAL";UpdateGpsButton();PostPreview();if(mapReady)MapView.CoreWebView2.PostWebMessageAsJson(JsonSerializer.Serialize(new{type="match-preview",point=currentPreview,focus=true}));FavoriteStatus.Text=L10n.Message(L10n.Text("手填收藏仅预览；明确加入GPS草稿后仍须手动保存。"));}
 private void MapDisplayChanged(object s,RoutedEventArgs e){if(!IsLoaded||fillingMapSettings||mapWorkspace is null)return;try{PersistMapState(mapWorkspace.State with{SelectedOnly=MapSelectedOnly.IsChecked==true,StartWithDevice=MapStartWithDevice.IsChecked==true,GoogleLayer=new[]{"roadmap","satellite","hybrid","terrain"}[Math.Max(0,GoogleLayerChoice.SelectedIndex)]});PostMapSettings();bool prior=stripSelectionChange;stripSelectionChange=true;try{_=PostPhotosAsync();}finally{stripSelectionChange=prior;}FavoriteStatus.Text=L10n.Message(L10n.Text("显示偏好已保存；不改变照片选择、匹配集合或GPS草稿。"));}catch(Exception){FavoriteStatus.Text=L10n.Message(L10n.Text("地图偏好未保存，已有文件保持；请重读后处理冲突。"));}}
 void PostMapSettings(bool restore=false){if(!mapReady||mapWorkspace is null)return;var v=restore&&currentMapPage==MapMessage.Page?mapWorkspace.State.OpenView:null;MapView.CoreWebView2.PostWebMessageAsJson(JsonSerializer.Serialize(new{type="map-settings",epoch=mapViewEpoch,layer=mapWorkspace.State.GoogleLayer,view=v,trackColor=ui.TrackColor,trackWidth=ui.TrackWidth==0?4:ui.TrackWidth}));}
 private void LocateDevice(object s,RoutedEventArgs e){if(!mapReady){FavoriteStatus.Text=L10n.Message(L10n.Text("地图不可用，保留上次视野或预设位置；可离线使用手填收藏。"));return;}mapViewEpoch++;mapLocationPending=true;PostMapSettings();MapView.CoreWebView2.PostWebMessageAsJson(JsonSerializer.Serialize(new{type="locate",epoch=mapViewEpoch}));FavoriteStatus.Text=L10n.Message(L10n.Text("请求系统定位；拒绝、超时或不可用时保持现有视野。"));}
 bool ReceiveMapWorkspace(string source,string json){if(!MapWorkspace.Message(source,json,out var type,out var epoch,out var view))return false;if(epoch!=mapViewEpoch)return true;if(type=="view-moved"){userMapMoved=true;mapLocationPending=false;ClearPlacePreview();photoRevision++;photoMapUpdate?.Cancel();return true;}if(type=="location-error"){mapLocationPending=false;FavoriteStatus.Text=L10n.Message(L10n.Text("系统定位不可用，保留上次视野或预设位置；未改照片。"));return true;}if(type=="located"){if(!mapLocationPending)return true;mapLocationPending=false;if(mapReady)MapView.CoreWebView2.PostWebMessageAsJson(JsonSerializer.Serialize(new{type="device-view",epoch,view}));return true;}if(type=="view"&&source==MapMessage.Page&&mapWorkspace is not null){try{PersistMapState(mapWorkspace.State with{OpenView=view});}catch(Exception){FavoriteStatus.Text=L10n.Message(L10n.Text("视野未持久化；原偏好保持，请核对多实例冲突。"));}}return true;}
}
